namespace RecipeShare.Models;

public class Recipe
{
    public string Title { get; set; } = "";
    public string Slug { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public int RatingCount { get; set; }
    public double AverageRating { get; set; }
}

public class CategoryInfo
{
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
    public string Icon { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<CategoryInfo> _categories;
    private readonly List<Recipe> _recipes;
    private readonly object _lock = new();

    public RecipeService()
    {
        _categories = new List<CategoryInfo>
        {
            new() { Name = "Breakfast", Description = "Start your day with delicious morning meals", Icon = "🥞" },
            new() { Name = "Dinner", Description = "Hearty and satisfying evening recipes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and indulgent delights", Icon = "🍰" },
            new() { Name = "Vegetarian", Description = "Fresh and flavorful plant-based dishes", Icon = "🥗" }
        };

        _recipes = new List<Recipe>
        {
            // Breakfast
            new()
            {
                Title = "Fluffy Pancakes",
                Slug = "fluffy-pancakes",
                Category = "Breakfast",
                Description = "Light and airy pancakes perfect for a lazy weekend morning.",
                Ingredients = new() { "1½ cups all-purpose flour", "3½ tsp baking powder", "1 tbsp sugar", "¼ tsp salt", "1¼ cups milk", "1 egg", "3 tbsp melted butter" },
                Steps = new() { "Mix dry ingredients in a large bowl.", "Make a well in the center and pour in milk, egg, and melted butter.", "Whisk until smooth.", "Heat a griddle over medium-high heat and grease lightly.", "Pour batter onto the griddle, using about ¼ cup for each pancake.", "Cook until bubbles form on the surface, then flip and cook until golden brown." },
                RatingCount = 12, AverageRating = 4.5
            },
            new()
            {
                Title = "Avocado Toast",
                Slug = "avocado-toast",
                Category = "Breakfast",
                Description = "Simple, healthy, and utterly delicious avocado on crispy toast.",
                Ingredients = new() { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes", "1 tbsp olive oil" },
                Steps = new() { "Toast the bread until golden and crispy.", "Halve the avocado, remove the pit, and scoop into a bowl.", "Mash with lemon juice, salt, and pepper.", "Spread the avocado mixture onto the toast.", "Drizzle with olive oil and sprinkle with red pepper flakes." },
                RatingCount = 8, AverageRating = 4.2
            },
            new()
            {
                Title = "Berry Smoothie Bowl",
                Slug = "berry-smoothie-bowl",
                Category = "Breakfast",
                Description = "A thick and creamy smoothie bowl loaded with fresh berries and granola.",
                Ingredients = new() { "1 cup frozen mixed berries", "1 banana", "½ cup Greek yogurt", "¼ cup almond milk", "Granola for topping", "Fresh berries for topping", "Honey drizzle" },
                Steps = new() { "Blend frozen berries, banana, yogurt, and almond milk until thick and smooth.", "Pour into a bowl.", "Top with granola, fresh berries, and a drizzle of honey.", "Serve immediately." },
                RatingCount = 5, AverageRating = 4.8
            },

            // Dinner
            new()
            {
                Title = "Garlic Butter Salmon",
                Slug = "garlic-butter-salmon",
                Category = "Dinner",
                Description = "Pan-seared salmon with a rich garlic butter sauce.",
                Ingredients = new() { "4 salmon fillets", "4 tbsp butter", "4 cloves garlic, minced", "2 tbsp lemon juice", "1 tbsp fresh parsley, chopped", "Salt and pepper to taste" },
                Steps = new() { "Season salmon fillets with salt and pepper.", "Heat a skillet over medium-high heat with a drizzle of oil.", "Cook salmon skin-side up for 4 minutes, then flip.", "Add butter and garlic to the pan.", "Baste salmon with the garlic butter for 3-4 minutes.", "Squeeze lemon juice over the top and garnish with parsley." },
                RatingCount = 15, AverageRating = 4.7
            },
            new()
            {
                Title = "Chicken Stir-Fry",
                Slug = "chicken-stir-fry",
                Category = "Dinner",
                Description = "Quick and colorful chicken stir-fry with crisp vegetables.",
                Ingredients = new() { "2 chicken breasts, sliced", "1 red bell pepper, sliced", "1 cup broccoli florets", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic, minced", "1 tsp fresh ginger, grated" },
                Steps = new() { "Toss chicken slices with cornstarch, salt, and pepper.", "Heat sesame oil in a wok over high heat.", "Stir-fry chicken until golden, then remove.", "Add garlic, ginger, and vegetables to the wok.", "Stir-fry for 3-4 minutes until crisp-tender.", "Return chicken to the wok, add soy sauce, and toss to combine." },
                RatingCount = 10, AverageRating = 4.3
            },

            // Desserts
            new()
            {
                Title = "Chocolate Lava Cake",
                Slug = "chocolate-lava-cake",
                Category = "Desserts",
                Description = "Rich chocolate cake with a molten center that oozes pure decadence.",
                Ingredients = new() { "4 oz dark chocolate", "½ cup butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tbsp flour", "Butter and cocoa for ramekins" },
                Steps = new() { "Preheat oven to 425°F (220°C).", "Melt chocolate and butter together in a microwave or double boiler.", "Stir in powdered sugar until smooth.", "Whisk in eggs and egg yolks.", "Fold in flour until just combined.", "Pour into greased and cocoa-dusted ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft.", "Invert onto plates and serve immediately." },
                RatingCount = 20, AverageRating = 4.9
            },
            new()
            {
                Title = "Classic Tiramisu",
                Slug = "classic-tiramisu",
                Category = "Desserts",
                Description = "An Italian classic with layers of coffee-soaked ladyfingers and mascarpone cream.",
                Ingredients = new() { "6 egg yolks", "¾ cup sugar", "1¼ cups mascarpone cheese", "2 cups heavy cream", "2 cups strong espresso, cooled", "3 tbsp coffee liqueur", "24 ladyfinger biscuits", "Cocoa powder for dusting" },
                Steps = new() { "Whisk egg yolks and sugar until thick and pale.", "Add mascarpone and mix until smooth.", "Whip heavy cream to stiff peaks and fold into the mascarpone mixture.", "Combine espresso and coffee liqueur in a shallow dish.", "Briefly dip ladyfingers in the coffee mixture and layer in a dish.", "Spread half the cream mixture over the ladyfingers.", "Repeat with another layer of dipped ladyfingers and cream.", "Refrigerate for at least 4 hours, then dust with cocoa powder." },
                RatingCount = 18, AverageRating = 4.8
            },

            // Vegetarian
            new()
            {
                Title = "Mushroom Risotto",
                Slug = "mushroom-risotto",
                Category = "Vegetarian",
                Description = "Creamy Italian risotto with earthy wild mushrooms and Parmesan.",
                Ingredients = new() { "1½ cups Arborio rice", "4 cups vegetable broth, warm", "8 oz mixed mushrooms, sliced", "1 onion, diced", "2 cloves garlic, minced", "½ cup white wine", "½ cup grated Parmesan", "2 tbsp butter", "2 tbsp olive oil", "Fresh thyme" },
                Steps = new() { "Sauté mushrooms in olive oil until golden, then set aside.", "In the same pan, cook onion and garlic in butter until soft.", "Add rice and stir for 1-2 minutes until translucent.", "Pour in white wine and stir until absorbed.", "Add broth one ladle at a time, stirring until each is absorbed.", "Continue for about 18-20 minutes until rice is creamy and al dente.", "Stir in mushrooms, Parmesan, and fresh thyme.", "Season and serve immediately." },
                RatingCount = 14, AverageRating = 4.6
            },
            new()
            {
                Title = "Caprese Salad",
                Slug = "caprese-salad",
                Category = "Vegetarian",
                Description = "A fresh and elegant Italian salad with ripe tomatoes and creamy mozzarella.",
                Ingredients = new() { "3 large ripe tomatoes", "8 oz fresh mozzarella", "Fresh basil leaves", "3 tbsp extra virgin olive oil", "1 tbsp balsamic glaze", "Salt and pepper to taste" },
                Steps = new() { "Slice tomatoes and mozzarella into ¼-inch thick rounds.", "Arrange alternating slices of tomato and mozzarella on a platter.", "Tuck fresh basil leaves between the slices.", "Drizzle with olive oil and balsamic glaze.", "Season with salt and pepper.", "Serve immediately at room temperature." },
                RatingCount = 7, AverageRating = 4.4
            }
        };
    }

    public List<CategoryInfo> GetCategories()
    {
        lock (_lock)
        {
            return _categories.ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetRecipe(string category, string slug)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r =>
                r.Category.Equals(category, StringComparison.OrdinalIgnoreCase) &&
                r.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));
        }
    }

    public void AddRating(string category, string slug, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r =>
                r.Category.Equals(category, StringComparison.OrdinalIgnoreCase) &&
                r.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));

            if (recipe is not null && stars >= 1 && stars <= 5)
            {
                var totalRating = recipe.AverageRating * recipe.RatingCount;
                recipe.RatingCount++;
                recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
            }
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Slug = recipe.Title.ToLower()
                .Replace(" ", "-")
                .Replace("'", "")
                .Replace("\"", "");
            _recipes.Add(recipe);
        }
    }
}

