    public List<CategoryInfo> GetCategories()
    {
        lock (_lock)
        {
            return _categories.ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetRecipe(string category, string slug)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r =>
                r.Category.Equals(category, StringComparison.OrdinalIgnoreCase) &&
                r.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));
        }
    }

    public void AddRating(string category, string slug, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r =>
                r.Category.Equals(category, StringComparison.OrdinalIgnoreCase) &&
                r.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));

            if (recipe is not null && stars >= 1 && stars <= 5)
            {
                var totalRating = recipe.AverageRating * recipe.RatingCount;
                recipe.RatingCount++;
                recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
            }
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Slug = recipe.Title.ToLower()
                .Replace(" ", "-")
                .Replace("'", "")
                .Replace("\"", "");
            _recipes.Add(recipe);
        }
    }
}

