    @foreach (var category in categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <div style="font-size: 3rem;">@category.Icon</div>
                    <h5 class="card-title mt-2">@category.Name</h5>
                    <p class="card-text">@category.Description</p>
                    <a href="recipes/@category.Name.ToLower()" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

