             <label for="steps" class="form-label">Steps (one per line)</label>
             <InputTextArea id="steps" @bind-Value="stepsText" class="form-control" rows="6" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
